<?php
class Film { private $pdo; public function __construct($pdo){$this->pdo=$pdo;} public function all(){return $this->pdo->query('SELECT * FROM film ORDER BY judul')->fetchAll();} public function find($id){$s=$this->pdo->prepare('SELECT * FROM film WHERE id=?');$s->execute([$id]);return $s->fetch();} public function save($d){$s=$this->pdo->prepare('INSERT INTO film(judul,genre,durasi,usia,sinopsis) VALUES(?,?,?,?,?)');return $s->execute([$d['judul'],$d['genre'],$d['durasi'],$d['usia'],$d['sinopsis']]);} public function update($id,$d){$s=$this->pdo->prepare('UPDATE film SET judul=?,genre=?,durasi=?,usia=?,sinopsis=? WHERE id=?');return $s->execute([$d['judul'],$d['genre'],$d['durasi'],$d['usia'],$d['sinopsis'],$id]);} public function delete($id){$s=$this->pdo->prepare('DELETE FROM film WHERE id=?');$s->execute([$id]);return $s->rowCount();}}
?>
